        benchmark: Annotated[Optional[StrictStr], Field(description="Benchmark narrows to the runs measured against these tasks: one, or several separated by commas, any of which a run may have measured.")] = None,
        system: Annotated[Optional[StrictStr], Field(description="System narrows to the runs of one system under test — which is also how a baseline's runs are listed, since a baseline is a system that was run.")] = None,
        study: Annotated[Optional[StrictStr], Field(description="Study narrows to the runs belonging to one study.")] = None,
        completion: Annotated[Optional[StrictStr], Field(description="Completion narrows by the DERIVED completion: complete, partial, inconsistent or unknown. `partial` is the query that finds runs whose numbers were published before they finished. Anything outside those four is refused rather than quietly matching nothing.")] = None,
        since: Annotated[Optional[StrictStr], Field(description="Since bounds the listing to runs that STARTED at or after this RFC3339 instant. A run whose start is unrecorded never satisfies a bounded filter — an unknown date is not evidence of falling in a range.")] = None,
