        category: Annotated[Optional[StrictStr], Field(description="Category keeps, of each run's measures, those whose category is one of these (comma-separated) or lies under one: `vs-claude-code` keeps `vs-claude-code/search`. It narrows a run's measures and never drops the run.")] = None,
